package main

import (
	"fmt"
	"net"
	"os"
	"os/signal"
	"syscall"
	"time"

	"golang.org/x/net/icmp"
	"golang.org/x/net/ipv4"
	"golang.org/x/net/ipv6"
)

const (
	defaultCount = 20
	version      = "pingu: v-rev9c2e3df"
)

type Options struct {
	host      string
	count     int
	privilege bool
}

func main() {
	opts := parseArgs()
	if opts == nil {
		os.Exit(1)
	}

	// Resolve hostname to IP
	addr, err := net.ResolveIPAddr("ip", opts.host)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] failed to resolve hostname: %v\n", err)
		os.Exit(1)
	}

	network := "ip4:icmp"
	if addr.IP.To4() == nil {
		network = "ip6:icmp"
	}

	// Create ICMP connection
	conn, err := icmp.ListenPacket(network, "0.0.0.0")
	if err != nil {
		fmt.Fprintf(os.Stderr, "[ ERROR ] %v\n", err)
		os.Exit(1)
	}
	defer conn.Close()

	fmt.Printf("PING %s (%s) type `Ctrl-C` to abort\n", opts.host, addr.String())

	// Setup signal handler for Ctrl+C
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT)

	// Track responses
	var times []time.Duration
	transmitted := 0
	received := 0

	// Ping loop
	seq := 0
	done := make(chan bool)

	go func() {
		for {
			select {
			case <-sigChan:
				done <- true
				return
			default:
			}

			if opts.count > 0 && seq >= opts.count {
				done <- true
				return
			}

			// Create ICMP message
			var msg icmp.Message
			if addr.IP.To4() != nil {
				msg = icmp.Message{
					Type: ipv4.ICMPTypeEcho,
					Code: 0,
					Body: &icmp.Echo{
						ID:  os.Getpid() & 0xffff,
						Seq: seq,
						Data: []byte("abcdefghijklmnopqrst"),
					},
				}
			} else {
				msg = icmp.Message{
					Type: ipv6.ICMPTypeEchoRequest,
					Code: 0,
					Body: &icmp.Echo{
						ID:  os.Getpid() & 0xffff,
						Seq: seq,
						Data: []byte("abcdefghijklmnopqrst"),
					},
				}
			}

			bytes, err := msg.Marshal(nil)
			if err != nil {
				fmt.Fprintf(os.Stderr, "[ ERROR ] %v\n", err)
				done <- true
				return
			}

			sendTime := time.Now()
			transmitted++

			_, err = conn.WriteTo(bytes, addr)
			if err != nil {
				fmt.Fprintf(os.Stderr, "[ ERROR ] an error occurred when running ping: %v\n", err)
				done <- true
				return
			}

			// Read response with timeout
			conn.SetReadDeadline(time.Now().Add(4 * time.Second))
			resp := make([]byte, 1024)
			n, remoteAddr, err := conn.ReadFrom(resp)
			if err != nil {
				// Timeout
				seq++
				continue
			}

			recvTime := time.Now()
			duration := recvTime.Sub(sendTime)

			// Parse response
			var rm *icmp.Message
			if addr.IP.To4() != nil {
				rm, err = icmp.ParseMessage(ipv4.ICMPTypeEchoReply, resp[:n])
			} else {
				rm, err = icmp.ParseMessage(ipv6.ICMPTypeEchoReply, resp[:n])
			}

			if err != nil {
				seq++
				continue
			}

			body, ok := rm.Body.(*icmp.Echo)
			if !ok {
				seq++
				continue
			}

			if body.Seq != seq {
				seq++
				continue
			}

			received++
			times = append(times, duration)

			// Print with ASCII art
			ttl := 64
			viz := visualize(duration)
			fmt.Printf(" %s seq=%d 32bytes from %s: ttl=%d time=%s\n", viz, seq, remoteAddr.String(), ttl, formatDuration(duration))

			seq++
		}
	}()

	<-done

	// Print statistics
	fmt.Printf("\n───────── %s ping statistics ─────────\n", opts.host)

	loss := 0
	if transmitted > 0 {
		loss = ((transmitted - received) * 100) / transmitted
	}
	fmt.Printf("PACKET STATISTICS: %d transmitted => %d received (%d%% loss)\n", transmitted, received, loss)

	if len(times) > 0 {
		minTime := times[0]
		maxTime := times[0]
		var total time.Duration

		for _, t := range times {
			total += t
			if t < minTime {
				minTime = t
			}
			if t > maxTime {
				maxTime = t
			}
		}

		avg := total / time.Duration(len(times))

		// Calculate stddev
		var variance float64
		for _, t := range times {
			diff := float64(t - avg)
			variance += diff * diff
		}
		variance /= float64(len(times))
		stddev := time.Duration(int64(sqrt(variance)))

		fmt.Printf("ROUND TRIP: min=%s avg=%s max=%s stddev=%s\n",
			formatDuration(minTime),
			formatDuration(avg),
			formatDuration(maxTime),
			formatDuration(stddev))
	} else {
		fmt.Printf("ROUND TRIP: min=0s avg=0s max=0s stddev=0s\n")
	}
}

func parseArgs() *Options {
	opts := &Options{
		count: defaultCount,
	}

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]

		if arg == "-h" || arg == "--help" {
			printHelp()
			os.Exit(0)
		} else if arg == "-V" || arg == "--version" {
			fmt.Println(version)
			os.Exit(0)
		} else if arg == "-P" || arg == "--privilege" {
			opts.privilege = true
		} else if arg == "-c" || arg == "--count" {
			if i+1 < len(os.Args) {
				_, err := fmt.Sscanf(os.Args[i+1], "%d", &opts.count)
				if err != nil {
					fmt.Fprintf(os.Stderr, "[ ERROR ] invalid count value\n")
					return nil
				}
				i++
			} else {
				fmt.Fprintf(os.Stderr, "[ ERROR ] -c requires an argument\n")
				return nil
			}
		} else if arg[0] == '-' {
			fmt.Fprintf(os.Stderr, "[ ERROR ] unknown option: %s\n", arg)
			return nil
		} else {
			opts.host = arg
		}
	}

	if opts.host == "" {
		fmt.Fprintf(os.Stderr, "[ ERROR ] must requires an argument\n")
		return nil
	}

	return opts
}

func printHelp() {
	fmt.Println(`Usage:
  pingu [OPTIONS] HOST

` + "`ping` command but with pingu" + `

Application Options:
  -c, --count=     Stop after <count> replies (default: 20)
  -P, --privilege  Enable privileged mode
  -V, --version    Show version

Help Options:
  -h, --help       Show this help message
`)
}

func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	if d < time.Millisecond {
		return fmt.Sprintf("%v", d)
	}
	return d.String()
}

func visualize(duration time.Duration) string {
	// Convert duration to microseconds
	micros := int(duration.Microseconds())

	// Map response time to visualization
	// Faster responses get more hashes, slower responses get more dots
	width := 50
	var result []rune

	// Use a scale: map microseconds to a position
	// Assume responses from 0-300µs are "normal"
	// Everything over 300µs gets more dots
	ratio := float64(micros) / 300.0
	if ratio > 1.0 {
		ratio = 1.0
	}

	fillCount := int(float64(width) * (1.0 - ratio))

	// Pattern: start and end with dots, fill with hashes or dots
	for i := 0; i < width; i++ {
		if i < fillCount {
			if i%3 == 0 {
				result = append(result, '.')
			} else if i%3 == 1 {
				result = append(result, '.')
			} else {
				result = append(result, ' ')
			}
		} else {
			result = append(result, '#')
		}
	}

	return string(result)
}

func sqrt(x float64) float64 {
	if x < 0 {
		return 0
	}
	z := x
	for i := 0; i < 10; i++ {
		z = (z + x/z) / 2
	}
	return z
}
