					},
				}
			} else {
				msg = icmp.Message{
					Type: ipv6.ICMPTypeEchoRequest,
					Code: 0,
					Body: &icmp.Echo{
						ID:  os.Getpid() & 0xffff,
						Seq: seq,
						Data: []byte("abcdefghijklmnopqrst"),
					},
				}
			}

