func icmpToBytes(echo ICMPEcho) []byte {
	bytes := make([]byte, 40)
	bytes[0] = echo.Type
	bytes[1] = echo.Code
	bytes[2] = 0
	bytes[3] = 0
	bytes[4] = byte(echo.ID >> 8)
	bytes[5] = byte(echo.ID & 0xff)
	bytes[6] = byte(echo.Seq >> 8)
	bytes[7] = byte(echo.Seq & 0xff)
	copy(bytes[8:], echo.Data[:])

	// Calculate checksum
	checksum := calculateChecksum(bytes)
	bytes[2] = byte(checksum >> 8)
	bytes[3] = byte(checksum & 0xff)

	return bytes
