func bytesToICMP(data []byte) ICMPEcho {
	echo := ICMPEcho{}
	if len(data) >= 8 {
		echo.Type = data[0]
		echo.Code = data[1]
		echo.Checksum = uint16(data[2])<<8 | uint16(data[3])
		echo.ID = uint16(data[4])<<8 | uint16(data[5])
		echo.Seq = uint16(data[6])<<8 | uint16(data[7])
		if len(data) >= 40 {
			copy(echo.Data[:], data[8:40])
		}
	}
	return echo
