		var total time.Duration

		for _, t := range times {
			total += t
			if t < minTime {
				minTime = t
			}
			if t > maxTime {
				maxTime = t
			}
		}

		avg := total / time.Duration(len(times))

		// Calculate stddev
		var variance float64
		for _, t := range times {
			diff := float64(t - avg)
			variance += diff * diff
		}
		variance /= float64(len(times))
		stddev := time.Duration(int64(math.Sqrt(variance)))

		fmt.Printf("ROUND TRIP: min=%s avg=%s max=%s stddev=%s\n",
			formatDuration(minTime),
			formatDuration(avg),
			formatDuration(maxTime),
			formatDuration(stddev))
	} else {
