	}
}

func parseArgs() *Options {
	opts := &Options{
		count: defaultCount,
	}

	for i := 1; i < len(os.Args); i++ {
		arg := os.Args[i]

		if arg == "-h" || arg == "--help" {
			printHelp()
			os.Exit(0)
		} else if arg == "-V" || arg == "--version" {
			fmt.Println(version)
			os.Exit(0)
		} else if arg == "-P" || arg == "--privilege" {
			opts.privilege = true
		} else if arg == "-c" || arg == "--count" {
			if i+1 < len(os.Args) {
				count, err := strconv.Atoi(os.Args[i+1])
				if err != nil {
					fmt.Fprintf(os.Stderr, "[ ERROR ] invalid count value\n")
					return nil
				}
				opts.count = count
				i++
			} else {
				fmt.Fprintf(os.Stderr, "[ ERROR ] -c requires an argument\n")
				return nil
			}
		} else if strings.HasPrefix(arg, "--count=") {
			// Handle --count=N format
			parts := strings.Split(arg, "=")
			if len(parts) != 2 {
				fmt.Fprintf(os.Stderr, "[ ERROR ] invalid count format\n")
				return nil
			}
			count, err := strconv.Atoi(parts[1])
			if err != nil {
