func formatDuration(d time.Duration) string {
	if d == 0 {
		return "0s"
	}
	if d < time.Millisecond {
		return fmt.Sprintf("%v", d)
	}
	return d.String()
}

func visualize(duration time.Duration) string {
	// Convert duration to microseconds
	micros := float64(duration.Microseconds())

	// Map response time to visualization
	width := 50
	var result []rune

	// Use a scale: normalize around 100µs baseline
	// Faster responses get more hashes, slower responses get more dots
	baseTime := 100.0
	ratio := micros / baseTime
	if ratio > 1.0 {
		ratio = 1.0
	}

	fillCount := int(float64(width) * (1.0 - ratio))

	// Pattern: dots and spaces for slow, hashes for fast
	for i := 0; i < width; i++ {
		if i < fillCount {
			if i%3 == 0 || i%3 == 1 {
				result = append(result, '.')
			} else {
				result = append(result, ' ')
			}
		} else {
			result = append(result, '#')
		}
	}

	return string(result)
}
